import type { MetadataRoute } from "next";
import { FILE_HANDLER_ACCEPT, SHARE_ACCEPT_TYPES } from "@/lib/pwa/open-with";
import { SHARE_TARGET_ACTION, SHARE_TARGET_FILE_FIELD } from "@/lib/pwa/share-target";

/** Metadata routes are Route Handlers; `output: "export"` requires this. */
export const dynamic = "force-static";

/**
 * Installable-app metadata. Icons are the "seam" mark on its accent-900 tile,
 * generated by scripts/generate-brand-assets.mjs.
 *
 * The two OS integration points below are declarations only — every browser
 * that does not implement them ignores the key and the app installs exactly as
 * it did before. Neither is written as a hand-rolled `public/manifest.webmanifest`
 * and neither needs a cast: `MetadataRoute.Manifest` types both, `share_target`
 * down to `method: 'post'` and `multipart/form-data`
 * (next/dist/lib/metadata/types/manifest-types.d.ts:52-62) and `file_handlers`
 * at :19-24.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Transmute — Free Online File Conversion Tools",
    short_name: "Transmute",
    description:
      "Free, private, browser-based file conversion tools. Convert images, PDFs, audio, video, and more — no uploads, no sign-ups.",
    start_url: "/",
    display: "standalone",
    background_color: "#0f111c",
    theme_color: "#161826",
    categories: ["utilities", "productivity"],
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    /*
      Share sheet → Transmute. A POST target with no server behind it: the
      service worker answers this URL in `fetch` and hands the files to the
      page through the Cache API. src/lib/pwa/share-target.ts holds the whole
      arrangement and the reasoning for it.

      `params` names ONLY `files`. `title`, `text` and `url` are the other
      three the spec allows, and declaring any of them would put Transmute in
      the share sheet for plain text and links as well — a file converter
      offering itself as a destination for a shared URL is an over-claim, and
      the landing page would have nothing to do with it.
    */
    share_target: {
      action: SHARE_TARGET_ACTION,
      method: "post",
      enctype: "multipart/form-data",
      params: {
        files: [{ name: SHARE_TARGET_FILE_FIELD, accept: [...SHARE_ACCEPT_TYPES] }],
      },
    },
    /*
      "Open with → Transmute" in the OS file manager, for the formats derived
      in open-with.ts: an extension is declared only where at least five tools
      accept it, counted off `acceptFormats`. The page side is
      `window.launchQueue`, wired in src/components/pwa/LaunchQueueIntake.tsx,
      which does nothing at all in the browsers — most of them — that have no
      such object.

      `launch_handler` is declared below, and it REVERSES what stood here.

      This comment used to argue that declaring nothing "leaves the browser's
      own default in place, which is the honest answer to a question we cannot
      answer". The premise was wrong, and the spec says so: the default is
      `auto`, and `auto` is not neutral — it is "the user agent decides what
      context makes sense for the platform", with `navigate-existing` the
      documented typical choice on mobile. `navigate-existing` brings an
      existing window into focus AND NAVIGATES IT to the launch URL.

      So declaring nothing was never the safe option. It was the one option
      that left this app exposed to a window being navigated away mid-run — a
      tab that may be minutes into a conversion holding the user's only copy of
      the output, which is the exact thing `ServiceWorkerRegistration` refuses
      to do with an update. The question was answerable after all; it just
      needed the spec rather than an installed PWA.

      WHY `navigate-new` AND NOT `focus-existing`, which also never navigates:
      `LaunchQueueIntake` is mounted in exactly one place — `OpenWithClient`,
      which is `/open`, the same URL as this handler's `action`.
      `focus-existing` focuses whatever window is already open WITHOUT
      navigating it, so unless that window happens to be sitting on `/open`
      the consumer is not mounted, `setConsumer` is never called, and the file
      is silently dropped: the app pops to the front and nothing happens. A
      silent drop is worse here than a second window.

      `navigate-new` is the only mode whose behaviour is fully specified, whose
      file always reaches the page that can handle it, and whose worst case —
      an extra app window when one was already open — costs the user a click
      and nothing else.
    */
    launch_handler: { client_mode: "navigate-new" },
    file_handlers: [
      {
        action: SHARE_TARGET_ACTION,
        // The manifest type wants mutable arrays; open-with.ts keeps its copy
        // readonly so a caller cannot edit the declaration in place.
        accept: Object.fromEntries(
          Object.entries(FILE_HANDLER_ACCEPT).map(([mime, exts]) => [mime, [...exts]]),
        ),
      },
    ],
  };
}
